# Link crawl: BFS over a link graph with allow-list, depth cap, and visited set.
pages = {'https://a.example/': ['https://a.example/b', 'https://a.example/c'], 'https://a.example/b': ['https://a.example/d'], 'https://a.example/c': [], 'https://a.example/d': []}
allowed = ['https://a.example/']
def crawl(start, max_depth=2):
    seen, queue, order = {start}, [(start, 0)], []
    while queue:
        url, depth = queue.pop(0)
        order.append((url, depth))
        if depth >= max_depth: continue
        for link in pages.get(url, []):
            if link not in seen and any(link.startswith(a) for a in allowed):
                seen.add(link); queue.append((link, depth + 1))
    return order
for url, depth in crawl("https://a.example/"):
    print("  "*depth + url)

